for (const [language, additions] of Object.entries(TOLLROAD_STORY_STRINGS)) {
    Object.assign(STRINGS[language], additions);
    if (language === 'en') continue;
    for (const [key, translated] of Object.entries(additions)) {
        EVENT_NARRATIVE_TRANSLATIONS[language][TOLLROAD_STORY_STRINGS.en[key]] = translated;
    }
}

