function interpolate(template, vars = {}) {
    return String(template).replace(/\{(\w+)\}/g, (_, key) => vars[key] ?? '');
}

function resolveTextKey(keyOrText, vars = {}) {
    if (keyOrText && typeof keyOrText === 'object') {
        return [keyOrText.key || keyOrText.text || '', { ...vars, ...(keyOrText.vars || {}) }];
    }

    const raw = String(keyOrText ?? '');
    if (STRINGS.en[raw]) return [raw, vars];

    const alias = TEXT_ALIASES[raw];
    if (alias) return [alias, vars];

    for (const [pattern, resolver] of TEXT_PATTERNS) {
        const match = raw.match(pattern);
        if (match) {
            const [key, patternVars] = resolver(match);
            return [key, { ...patternVars, ...vars }];
        }
    }

    return [raw, vars];
}

// Languages with complete string coverage (menu + all in-game text). Only these are
// offered in the language selector. fr/de/ja/zh still have only the ~15 menu strings
// translated, so selecting them would show a mostly-English game and make the toggle
// feel broken (it appeared to do nothing / only flip to German). Add a code here once
// that language's translations are finished. LANGUAGE_OPTIONS is kept full so
// getLanguageName can still resolve labels for legacy settings.
const SUPPORTED_LANGUAGES = ['en', 'es', 'fr', 'ru'];

export function getLanguageOptions() {
    return LANGUAGE_OPTIONS.filter(option => SUPPORTED_LANGUAGES.includes(option.code));
}

export function normalizeLanguageCode(language) {
    const value = String(language || 'en');
    const lower = value.toLowerCase();
    const legacy = {
        english: 'en',
        spanish: 'es',
        'español': 'es',
        french: 'fr',
        'français': 'fr',
        german: 'de',
        deutsch: 'de',
        japanese: 'ja',
        '日本語': 'ja',
        chinese: 'zh',
        '中文': 'zh',
        russian: 'ru',
        'русский': 'ru',
    };
    return LANGUAGE_OPTIONS.some(option => option.code === lower)
        ? lower
        : legacy[lower] || 'en';
}

export function getLanguageName(code) {
    const normalized = normalizeLanguageCode(code);
    return LANGUAGE_OPTIONS.find(option => option.code === normalized)?.name || 'English';
}

export function getGameLanguage(sceneOrGame) {
    const game = sceneOrGame?.game || sceneOrGame;
    return normalizeLanguageCode(game?.language);
}

/**
 * Which plural form a count takes.
 *
 * English and Spanish have two. Russian has three, chosen by the last digit:
 * 1 ход, 2 хода, 5 ходов — and every number in the teens takes the third form,
 * so 11 is ходов, not ход. Getting this wrong is immediately visible to a
 * native reader, which is why the old `plural: n > 1 ? 's' : ''` trick could
 * not be extended past English.
 */
function pluralCategory(language, count) {
    const n = Math.abs(Math.trunc(Number(count) || 0));
    if (language === 'ru') {
        const last = n % 10;
        const lastTwo = n % 100;
        if (last === 1 && lastTwo !== 11) return 'one';
        if (last >= 2 && last <= 4 && (lastTwo < 12 || lastTwo > 14)) return 'few';
        return 'many';
    }
    // English, Spanish, French and German all split at exactly one, so they take
    // the default. Only add a branch above for a language that genuinely counts
    // differently — Russian's three forms are why this function exists.
    return n === 1 ? 'one' : 'many';
}

/**
 * Like t(), but resolves `<keyBase>.one` / `.few` / `.many` for `count`.
 *
 * `count` is also passed through as a variable, so a form can read
 * "{count} ходов" without the caller repeating it.
 */
export function tCount(sceneOrGame, keyBase, count, vars = {}) {
    const language = getGameLanguage(sceneOrGame);
    const category = pluralCategory(language, count);
    const locale = STRINGS[language] || {};
    const pick = (table) => table?.[`${keyBase}.${category}`] ?? table?.[`${keyBase}.many`];
    const template = pick(locale) ?? pick(STRINGS.en) ?? keyBase;
    return interpolate(template, { ...vars, count });
}

export function t(sceneOrGame, keyOrText, vars = {}) {
    const [key, resolvedVars] = resolveTextKey(keyOrText, vars);
    const language = getGameLanguage(sceneOrGame);
    const template = STRINGS[language]?.[key] || STRINGS.en[key] || key;
    return interpolate(template, resolvedVars);
}

export function translateRarity(sceneOrGame, rarity, fallback = '') {
    const language = getGameLanguage(sceneOrGame);
    const key = String(rarity || '').toLowerCase();
    return RARITY_TRANSLATIONS[language]?.[key] || fallback || (key ? key.charAt(0).toUpperCase() + key.slice(1) : '');
}

export function translateCardType(sceneOrGame, type) {
    const keyByType = {
        weapon: 'tooltip.weapon',
        armor: 'tooltip.armor',
        thorns: 'tooltip.thorns',
        potion: 'tooltip.potion',
        food: 'tooltip.food',
        magic: 'tooltip.magic',
        gem: 'tooltip.gem',
        amulet: 'tooltip.relic',
        key: 'tooltip.key',
        coin: 'tooltip.coins',
        crystal: 'tooltip.ruby',
    };
    return t(sceneOrGame, keyByType[type] || 'tooltip.card');
}

export function translateCharacterName(sceneOrGame, characterId) {
    const id = String(characterId || '').toLowerCase();
    return t(sceneOrGame, `character.${id}`);
}

export function translateGemEffect(sceneOrGame, effect) {
    const language = getGameLanguage(sceneOrGame);
    const key = String(effect || 'gem').toLowerCase();
    return GEM_EFFECT_TRANSLATIONS[language]?.[key] || (key ? key.charAt(0).toUpperCase() + key.slice(1) : t(sceneOrGame, 'tooltip.gem'));
}

export function translateDescription(sceneOrGame, description) {
    const language = getGameLanguage(sceneOrGame);
    const raw = String(description || '');
    return EVENT_NARRATIVE_TRANSLATIONS[language]?.[raw]
        || EVENT_TITLE_TRANSLATIONS[language]?.[raw]
        || DESCRIPTION_TRANSLATIONS[language]?.[raw]
        || raw;
}

export function translateItemName(sceneOrGame, data) {
    const language = getGameLanguage(sceneOrGame);
    const rawName = typeof data === 'string' ? data : (data?.name || '');
    const exact = EXACT_NAME_TRANSLATIONS[language]?.[rawName];
    if (exact) return exact;

    const item = typeof data === 'object' ? data : null;
    if (item?.type === 'weapon') {
        const rarity = translateRarity(sceneOrGame, item.rarity);
        const weaponKey = item.weaponType || rawName.split(' ').pop()?.toLowerCase();
        const weapon = WEAPON_TRANSLATIONS[language]?.[weaponKey] || rawName.replace(/^(Common|Uncommon|Rare|Epic|Legendary|Cursed)\s+/, '');
        return [rarity, weapon].filter(Boolean).join(' ');
    }

    if (item?.type === 'armor') {
        const rarity = translateRarity(sceneOrGame, item.rarity);
        const armorKey = item.armorType || rawName.replace(/^(Common|Uncommon|Rare|Epic|Legendary|Cursed)\s+/, '').replace(/\s+Armor$/, '').toLowerCase();
        const armor = ARMOR_TRANSLATIONS[language]?.[armorKey] || rawName.replace(/^(Common|Uncommon|Rare|Epic|Legendary|Cursed)\s+/, '');
        return [rarity, armor].filter(Boolean).join(' ');
    }

    const rarityMatch = rawName.match(/^(Common|Uncommon|Rare|Epic|Legendary|Cursed)\s+(.+)$/);
    if (rarityMatch) {
        return `${translateRarity(sceneOrGame, rarityMatch[1])} ${rarityMatch[2]}`;
    }

    return rawName;
}
